<?php require 'config/db.php';require 'includes/functions.php';require_role('requester');$uid=user()['id'];$rs=$conn->query("SELECT br.*,h.name hospital_name,(SELECT COUNT(*) FROM request_matches rm WHERE rm.request_id=br.id) matches FROM blood_requests br LEFT JOIN hospitals h ON h.id=br.hospital_id WHERE br.requester_id=$uid ORDER BY br.created_at DESC");$active=(int)$conn->query("SELECT COUNT(*) c FROM blood_requests WHERE requester_id=$uid AND status NOT IN ('completed','cancelled')")->fetch_assoc()['c'];$pageTitle='Requester Dashboard';include 'includes/header.php';?>
<section class="dashboard"><div class="container"><div class="dashboard-head"><div><span class="kicker">My rescue cases</span><h1>Requester dashboard</h1><p>Track donor matching and every request milestone.</p></div><a class="btn btn-primary" href="request-blood.php"><i class="fa-solid fa-bolt"></i> Request blood</a></div><div class="metric-grid"><div class="metric"><div class="icon"><i class="fa-solid fa-bolt"></i></div><strong><?=$active?></strong><span>Active requests</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-eye"></i></div><strong>Live</strong><span>Case tracking</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-lock"></i></div><strong>Safe</strong><span>Private contact</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-tower-broadcast"></i></div><strong>3→25</strong><span>Radius km</span></div></div><div class="panel"><h3>Your blood requests</h3><div class="table-wrap"><table class="table"><tr><th>Case</th><th>Patient</th><th>Blood</th><th>Matched</th><th>Status</th><th></th></tr><?php while($r=$rs->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['patient_name'])?><br><small><?=e($r['hospital_name'])?></small></td><td><b><?=e($r['blood_group'])?></b></td><td><?=$r['matches']?></td><td><?=e(status_label($r['status']))?></td><td><a class="btn btn-sm btn-ghost" href="request-view.php?id=<?=$r['id']?>">Track case</a></td></tr><?php endwhile;?></table></div></div></div></section><?php include 'includes/footer.php';?>
